"""Scene subsystem handler — emits the scene graph and main loop glue."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from src.core.engine_profile import EngineProfile

SCENE_HEADER = """\
#pragma once
// {name} — scene subsystem. Generated by sdl2-game-engine-starter.
#include "render/renderer.h"
#include "input/input_state.h"
#include <memory>
#include <vector>

namespace {ns}::scene {{

class Scene {{
public:
    virtual ~Scene() = default;
    virtual void on_enter() {{}}
    virtual void on_update(double dt) = 0;
    virtual void on_render(render::Renderer& r) = 0;
}};

class SceneStack {{
public:
    void push(std::unique_ptr<Scene> s);
    void pop();
    void update(double dt);
    void render(render::Renderer& r);

private:
    std::vector<std::unique_ptr<Scene>> stack_;
}};

}}  // namespace {ns}::scene
"""

SCENE_SOURCE = """\
// {name} — scene subsystem implementation.
#include "scene/scene_stack.h"

namespace {ns}::scene {{

void SceneStack::push(std::unique_ptr<Scene> s) {{
    if (s) {{ s->on_enter(); stack_.push_back(std::move(s)); }}
}}

void SceneStack::pop() {{ if (!stack_.empty()) stack_.pop_back(); }}

void SceneStack::update(double dt) {{
    if (!stack_.empty()) stack_.back()->on_update(dt);
}}

void SceneStack::render(render::Renderer& r) {{
    if (!stack_.empty()) stack_.back()->on_render(r);
}}

}}  // namespace {ns}::scene
"""


@dataclass(slots=True)
class SceneHandler:
    profile: EngineProfile

    def emit(self, project_root: Path) -> list[Path]:
        out_dir = project_root / "src" / "engine_cpp" / "scene"
        out_dir.mkdir(parents=True, exist_ok=True)
        ns = self.profile.name.replace("-", "_").lower()
        header = out_dir / "scene_stack.h"
        source = out_dir / "scene_stack.cpp"
        header.write_text(SCENE_HEADER.format(name=self.profile.name, ns=ns), encoding="utf-8")
        source.write_text(SCENE_SOURCE.format(name=self.profile.name, ns=ns), encoding="utf-8")
        return [header, source]